-- HORAS DO SERVIÇO = 2× AS DUTIES, v2 (26/11/2026, Márcio: «isso é pra todas as invoices nos 2 apps» · «mostrando o dobro do real, que está nas duties»).
-- O elo passa a morar na DUTY (um serviço junta várias duties): invoice_duties.service_id → invoice_services. Só exibição (lib/serviceHours.ts).
begin;
alter table public.invoice_duties add column if not exists service_id uuid references public.invoice_services(id) on delete set null;
create index if not exists invoice_duties_service_id_idx on public.invoice_duties(service_id);
-- v1 (de hoje cedo) guardava o elo no serviço: passa para a duty e a coluna sai
update public.invoice_duties d set service_id = s.id from public.invoice_services s where s.duty_id = d.id and d.service_id is null;
drop index if exists public.invoice_services_duty_id_idx;
alter table public.invoice_services drop column if exists duty_id;
